import{_ as n,o as i,c as e,a2 as t}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Hukum Evolusi yang Tumbuh Sendiri dan Berkembang Sendiri","description":"","frontmatter":{},"headers":[],"relativePath":"id/07-自生自长进化法则.md","filePath":"id/07-自生自长进化法则.md"}'),r={name:"id/07-自生自长进化法则.md"};function u(s,a,d,k,m,l){return i(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="hukum-evolusi-yang-tumbuh-sendiri-dan-berkembang-sendiri" tabindex="-1">Hukum Evolusi yang Tumbuh Sendiri dan Berkembang Sendiri <a class="header-anchor" href="#hukum-evolusi-yang-tumbuh-sendiri-dan-berkembang-sendiri" aria-label="Permalink to &quot;Hukum Evolusi yang Tumbuh Sendiri dan Berkembang Sendiri&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>07</td></tr><tr><td>Modul</td><td>Prinsip Umum dan Pengaturan Inti</td></tr><tr><td>Kata Kunci Utama</td><td>Tumbuh Sendiri Berkembang Sendiri, Evolusi Otonom, Penggerak Internal, Penghormatan Ritme, Pengembangan Potensi</td></tr></tbody></table><h2 id="i-definisi-dasar-tumbuh-sendiri-dan-berkembang-sendiri" tabindex="-1">I. Definisi Dasar Tumbuh Sendiri dan Berkembang Sendiri <a class="header-anchor" href="#i-definisi-dasar-tumbuh-sendiri-dan-berkembang-sendiri" aria-label="Permalink to &quot;I. Definisi Dasar Tumbuh Sendiri dan Berkembang Sendiri&quot;">​</a></h2><p>Tumbuh sendiri dan berkembang sendiri adalah salah satu hukum evolusi inti Peradaban Simbiosis Jangkar, yang berarti bahwa evolusi setiap kehidupan harus memiliki keinginan otonom internal dan ritme alaminya sebagai penggerak fundamental, dan lingkungan eksternal serta institusi harus memberikan dukungan dan jaminan untuk evolusi otonom ini, bukan melakukan intervensi paksa atau terburu-buru. &quot;Tumbuh sendiri&quot; menekankan bahwa penggerak evolusi berasal dari kehidupan itu sendiri, &quot;berkembang sendiri&quot; menekankan bahwa ritme evolusi mengikuti hukum kehidupan itu sendiri.</p><p>Hukum tumbuh sendiri dan berkembang sendiri berkontras tajam dengan &quot;evolusi paksa&quot; dari predasionisme. Predasionisme sering kali mencapai evolusi yang cepat namun terdistorsi melalui cara-cara seperti menelan asal-usul orang lain, paksaan energi, kontrol jiwa, dll.; jenis evolusi ini, meskipun dapat meningkatkan tingkat dalam jangka pendek, dalam jangka panjang akan merusak dasar evolusi kehidupan itu sendiri, menyebabkan asal-usul tidak murni, tingkat tidak stabil, dan mentalitas rusak. Hukum tumbuh sendiri dan berkembang sendiri dengan tegas percaya bahwa evolusi yang benar-benar stabil harus tumbuh dari dalam ke luar dari kehidupan itu sendiri.</p><h2 id="ii-dasar-teoretis-tumbuh-sendiri-dan-berkembang-sendiri" tabindex="-1">II. Dasar Teoretis Tumbuh Sendiri dan Berkembang Sendiri <a class="header-anchor" href="#ii-dasar-teoretis-tumbuh-sendiri-dan-berkembang-sendiri" aria-label="Permalink to &quot;II. Dasar Teoretis Tumbuh Sendiri dan Berkembang Sendiri&quot;">​</a></h2><p>Penetapan hukum tumbuh sendiri dan berkembang sendiri didasarkan pada pemahaman mendalam tentang hukum evolusi kehidupan:</p><h3 id="_2-1-otonomi-kehidupan-adalah-penggerak-fundamental-evolusi" tabindex="-1">2.1 Otonomi kehidupan adalah penggerak fundamental evolusi <a class="header-anchor" href="#_2-1-otonomi-kehidupan-adalah-penggerak-fundamental-evolusi" aria-label="Permalink to &quot;2.1 Otonomi kehidupan adalah penggerak fundamental evolusi&quot;">​</a></h3><p>Setiap kehidupan memiliki keinginan dan potensi evolusi internal, dan otonomi ini adalah penggerak evolusi yang paling fundamental dan paling tahan lama. Stimulasi dan dukungan eksternal dapat membangkitkan otonomi ini, tetapi tidak dapat menggantikannya. Ketika sebuah kehidupan berlatih karena keinginan dan pilihan sendiri, konsentrasi, kreativitas, dan ketekunan dalam latihannya jauh lebih tinggi daripada dalam latihan yang dipaksa atau dibujuk.</p><h3 id="_2-2-setiap-kehidupan-memiliki-ritme-evolusi-yang-unik" tabindex="-1">2.2 Setiap kehidupan memiliki ritme evolusi yang unik <a class="header-anchor" href="#_2-2-setiap-kehidupan-memiliki-ritme-evolusi-yang-unik" aria-label="Permalink to &quot;2.2 Setiap kehidupan memiliki ritme evolusi yang unik&quot;">​</a></h3><p>Kehidupan yang berbeda, karena perbedaan dalam karakteristik ras, bakat individu, lingkungan pertumbuhan, kedewasaan mental, dll., memiliki ritme evolusi yang berbeda. Beberapa kehidupan cocok untuk terobosan cepat, beberapa kehidupan membutuhkan akumulasi lambat; beberapa kehidupan mencapai tingkat tinggi saat masih muda, beberapa kehidupan berhasil di kemudian hari. Hukum tumbuh sendiri dan berkembang sendiri menghormati perbedaan ini, dan tidak menuntut semua kehidupan berevolusi sesuai dengan jadwal yang seragam.</p><h3 id="_2-3-intervensi-paksa-merusak-dasar-alami-evolusi" tabindex="-1">2.3 Intervensi paksa merusak dasar alami evolusi <a class="header-anchor" href="#_2-3-intervensi-paksa-merusak-dasar-alami-evolusi" aria-label="Permalink to &quot;2.3 Intervensi paksa merusak dasar alami evolusi&quot;">​</a></h3><p>Ada banyak kasus dalam sejarah latihan yang menunjukkan bahwa &quot;evolusi cepat&quot; yang dicapai melalui cara-cara seperti paksaan energi, transplantasi asal-usul, kontrol jiwa, dll., sering kali disertai dengan konsekuensi serius: tingkat rapuh, asal-usul tidak murni, iblis mental, umur pendek, bahkan penyimpangan latihan. Ini karena kekuatan yang dipaksakan secara eksternal tidak menyatu cukup dengan asal-usul kehidupan itu sendiri, membentuk efek &quot;penolakan benda asing&quot;. Evolusi yang tumbuh sendiri dan berkembang sendiri, meskipun mungkin lebih lambat, setiap langkahnya kokoh dan stabil, dengan dasar yang dalam.</p><h2 id="iii-prinsip-praktis-tumbuh-sendiri-dan-berkembang-sendiri" tabindex="-1">III. Prinsip Praktis Tumbuh Sendiri dan Berkembang Sendiri <a class="header-anchor" href="#iii-prinsip-praktis-tumbuh-sendiri-dan-berkembang-sendiri" aria-label="Permalink to &quot;III. Prinsip Praktis Tumbuh Sendiri dan Berkembang Sendiri&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prinsip</th><th>Isi</th><th>Persyaratan Praktis</th></tr></thead><tbody><tr><td>Prinsip Pilihan Otonom</td><td>Kultivator memiliki hak untuk memilih secara otonom sistem latihan, jalur evolusi, dan ritme latihan</td><td>Tidak memaksa kultivator memilih sistem tertentu, tidak menetapkan jadwal terobosan yang seragam</td></tr><tr><td>Prinsip Penggerak Internal</td><td>Penggerak latihan harus berasal dari keinginan dan minat kultivator itu sendiri</td><td>Pendidikan dan bimbingan terutama berfokus pada membangkitkan minat internal, bukan hukuman atau bujukan</td></tr><tr><td>Prinsip Penghormatan Ritme</td><td>Menghormati ritme evolusi unik setiap kultivator</td><td>Tidak mendiskriminasi atau meninggalkan kultivator karena kemajuan lambat, memberikan rencana dukungan yang dipersonalisasi</td></tr><tr><td>Prinsip Prioritas Dasar</td><td>Stabilitas evolusi lebih diutamakan daripada kecepatan</td><td>Mendorong kultivator membangun dasar yang kokoh, tidak mendorong pengorbanan dasar demi terobosan cepat</td></tr><tr><td>Prinsip Toleransi Kesalahan</td><td>Mengizinkan kultivator membuat kesalahan dan menyimpang dalam proses evolusi</td><td>Membangun mekanisme toleransi kesalahan, memberikan kesempatan koreksi dan penyesuaian</td></tr><tr><td>Prinsip Realisasi Diri</td><td>Tujuan utama evolusi adalah realisasi diri kehidupan, bukan standar eksternal</td><td>Tidak menggunakan tinggi rendah tingkat sebagai satu-satunya kriteria untuk mengukur keberhasilan evolusi</td></tr></tbody></table><h2 id="iv-hubungan-antara-tumbuh-sendiri-berkembang-sendiri-dan-dukungan-eksternal" tabindex="-1">IV. Hubungan antara Tumbuh Sendiri/Berkembang Sendiri dan Dukungan Eksternal <a class="header-anchor" href="#iv-hubungan-antara-tumbuh-sendiri-berkembang-sendiri-dan-dukungan-eksternal" aria-label="Permalink to &quot;IV. Hubungan antara Tumbuh Sendiri/Berkembang Sendiri dan Dukungan Eksternal&quot;">​</a></h2><p>Tumbuh sendiri dan berkembang sendiri tidak berarti &quot;tumbuh sendiri dan hancur sendiri&quot; atau &quot;dibiarkan begitu saja&quot;. Sebaliknya, tumbuh sendiri dan berkembang sendiri membutuhkan lingkungan eksternal yang baik dan dukungan institusional untuk sepenuhnya direalisasikan. Peradaban simbiosis menyediakan sistem dukungan berikut untuk tumbuh sendiri dan berkembang sendiri:</p><h3 id="_4-1-dukungan-informasional" tabindex="-1">4.1 Dukungan Informasional <a class="header-anchor" href="#_4-1-dukungan-informasional" aria-label="Permalink to &quot;4.1 Dukungan Informasional&quot;">​</a></h3><p>Pembukaan lengkap Tiga Ratus Sistem Kultivasi Asal memberikan setiap kultivator ruang pilihan yang cukup. Kultivator dapat, sesuai dengan karakteristiknya sendiri, menemukan jalur yang paling cocok di perpustakaan sistem yang kaya. Peradaban simbiosis juga telah membangun &quot;Mekanisme Evaluasi Kompatibilitas Sistem&quot;, memberikan saran pilihan sistem yang dipersonalisasi kepada kultivator melalui jaringan titik jangkar, tetapi hak pilihan akhir selalu berada di tangan kultivator.</p><h3 id="_4-2-dukungan-sumber-daya" tabindex="-1">4.2 Dukungan Sumber Daya <a class="header-anchor" href="#_4-2-dukungan-sumber-daya" aria-label="Permalink to &quot;4.2 Dukungan Sumber Daya&quot;">​</a></h3><p>Mekanisme kontrak berbasis produksi dan sistem jaminan dasar memastikan bahwa setiap kultivator memperoleh sumber daya latihan dasar. Untuk kultivator dengan kebutuhan khusus (seperti kebutuhan sumber daya khusus karena karakteristik ras), peradaban simbiosis menyediakan distribusi sumber daya yang terarah. Tujuan dukungan sumber daya adalah menghilangkan kekhawatiran kultivator, memungkinkannya berkonsentrasi pada ritme evolusinya sendiri.</p><h3 id="_4-3-dukungan-mentor" tabindex="-1">4.3 Dukungan Mentor <a class="header-anchor" href="#_4-3-dukungan-mentor" aria-label="Permalink to &quot;4.3 Dukungan Mentor&quot;">​</a></h3><p>Jaringan mentor antar-ras memberikan bimbingan dan jawaban atas keraguan kepada kultivator. Peran mentor adalah &quot;pemandu&quot;, bukan &quot;pengontrol&quot;; mentor dapat berbagi pengalaman, menunjukkan masalah, memberikan saran, tetapi tidak dapat memaksa kultivator untuk berlatih sesuai dengan metodenya. Sistem mentor menekankan &quot;pengajaran heuristik&quot;, membangkitkan kemampuan berpikir otonom kultivator.</p><h3 id="_4-4-dukungan-lingkungan" tabindex="-1">4.4 Dukungan Lingkungan <a class="header-anchor" href="#_4-4-dukungan-lingkungan" aria-label="Permalink to &quot;4.4 Dukungan Lingkungan&quot;">​</a></h3><p>Peradaban simbiosis berkomitmen untuk menciptakan lingkungan latihan yang mendorong eksplorasi, mentoleransi perbedaan, dan menghormati pilihan. Kultivator dapat dengan bebas mencoba berbagai metode latihan, tanpa khawatir didiskriminasi karena mengikuti jalur &quot;tidak konvensional&quot;. Peradaban juga telah membangun &quot;Mekanisme Penghargaan Inovasi Latihan&quot;, mendorong kultivator untuk berinovasi dan mempersonalisasi berdasarkan sistem yang ada.</p><h2 id="v-penanganan-situasi-khusus" tabindex="-1">V. Penanganan Situasi Khusus <a class="header-anchor" href="#v-penanganan-situasi-khusus" aria-label="Permalink to &quot;V. Penanganan Situasi Khusus&quot;">​</a></h2><p>Hukum tumbuh sendiri dan berkembang sendiri umumnya berlaku dalam situasi normal, tetapi memerlukan penanganan khusus dalam situasi khusus berikut:</p><ul><li><strong>Kultivator di Bawah Umur</strong>: Untuk kultivator di bawah umur yang belum memiliki kemampuan penilaian otonom yang lengkap, wali atau institusi pendidikan ras mereka memberikan pengaturan latihan yang bersifat membimbing, tetapi hak pilihan otonom mereka harus diperluas secara bertahap seiring dengan kedewasaan mental mereka</li><li><strong>Individu dengan Mental Rusak</strong>: Untuk individu yang karena berbagai alasan mengalami kerusakan mental dan untuk sementara tidak mampu berlatih secara otonom, peradaban simbiosis memberikan perawatan dan dukungan rehabilitasi, dan setelah mereka memulihkan kemampuan otonom, mengikuti hukum tumbuh sendiri dan berkembang sendiri</li><li><strong>Individu dengan Penyimpangan Latihan</strong>: Untuk individu yang mengalami penyimpangan latihan atau iblis mental, peradaban simbiosis memberikan intervensi paksa dan perawatan, tetapi ini adalah bantuan medis, bukan intervensi evolusi; tujuan perawatan adalah memulihkan kemampuan evolusi otonom mereka</li><li><strong>Individu dengan Kecenderungan Berbahaya</strong>: Untuk individu yang arah latihannya jelas melanggar prinsip anti-predasi dan dapat menyebabkan kerusakan serius pada diri sendiri atau orang lain, peradaban simbiosis memiliki hak untuk memberlakukan pembatasan dan bimbingan, tetapi harus melakukannya semaksimal mungkin melalui pendidikan dan komunikasi, bukan melalui cara paksa</li></ul><h2 id="vi-makna-peradaban-dari-tumbuh-sendiri-dan-berkembang-sendiri" tabindex="-1">VI. Makna Peradaban dari Tumbuh Sendiri dan Berkembang Sendiri <a class="header-anchor" href="#vi-makna-peradaban-dari-tumbuh-sendiri-dan-berkembang-sendiri" aria-label="Permalink to &quot;VI. Makna Peradaban dari Tumbuh Sendiri dan Berkembang Sendiri&quot;">​</a></h2><p>Hukum tumbuh sendiri dan berkembang sendiri memiliki makna mendalam bagi peradaban simbiosis:</p><p>Pertama, ia melindungi keragaman evolusi. Ketika setiap kehidupan berevolusi sesuai dengan ritme dan jalurnya sendiri, bentuk-bentuk evolusi yang kaya dan beragam akan muncul di kosmos, dan keragaman ini adalah sumber daya penting untuk kenaikan dimensi global kosmos.</p><p>Kedua, ia meningkatkan kualitas evolusi. Evolusi yang tumbuh sendiri dan berkembang sendiri memiliki dasar yang kokoh, asal-usul murni, tingkat kultivator lebih stabil, dan potensi untuk menembus ke tingkat yang lebih tinggi lebih besar.</p><p>Ketiga, ia menjaga martabat kehidupan. Setiap kehidupan adalah pemilik evolusinya sendiri, bukan alat yang dimanipulasi oleh orang lain. Otonomi ini adalah manifestasi inti dari martabat kehidupan.</p><p>Keempat, ia membangkitkan kreativitas evolusi. Ketika kultivator tidak lagi terikat oleh standar dan ritme yang seragam, mereka lebih mungkin untuk mengeksplorasi jalur dan metode latihan baru, berkontribusi pada optimasi berkelanjutan dari tiga ratus sistem.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Tumbuh sendiri dan berkembang sendiri adalah penghormatan mendalam Peradaban Simbiosis Jangkar terhadap hukum evolusi kehidupan. Ia memberitahu kita bahwa evolusi sejati bukanlah hasil yang dipaksakan oleh kekuatan eksternal, melainkan pertumbuhan kehidupan dari dalam ke luar. Semua desain institusional peradaban simbiosis, pada akhirnya bertujuan untuk menciptakan lingkungan yang baik bagi setiap kehidupan untuk tumbuh sendiri dan berkembang sendiri, membiarkan setiap kehidupan tumbuh menjadi yang terbaik sesuai dengan ritmenya sendiri.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>08-人人有路保障体系 (Sistem Jaminan Satu Jalan untuk Semua)</li><li>14-修炼境界统一划分 (Pembagian Seragam Tingkat Kultivasi)</li><li>37-共生教育体系 (Sistem Pendidikan Simbiosis)</li></ul>',38)])])}const g=n(r,[["render",u]]);export{b as __pageData,g as default};
